#include "engine/world_road_traffic_core.h"
#include "engine/world_follow_camera_safety.h"
#include "engine/world_first_journey.h"
#include <cstdio>
#include <cstdlib>
#include <limits>
#include <string>
using namespace world_road_traffic_core;
static unsigned checks=0;
static void need(bool ok,const char*label){++checks;if(!ok){std::fprintf(stderr,"FAIL %s check%u\n",label,checks);std::exit(1);}}
static bool ground(double,double,double ref,double&out,const void*){out=ref;return std::isfinite(ref);}
static bool clear(double,double,double,double,double,double,double,const void*){return true;}
static WorldRoadTrafficConfig test_config;
static Core make(){Core c;need(c.route.build(test_config),"default supported route");const double shape[6][4]={{.35,.49,.54,1.84},{.35,.80,.44,1.86},{.35,.50,.55,1.84},{.35,.51,.59,1.84},{.7,2.71,1.38,3.17},{.9,.91,3.09,2.42}};for(unsigned i=0;i<6;i++){auto&f=c.profiles[i];f.radius=shape[i][0];f.front=shape[i][1];f.rear=shape[i][2];f.height=shape[i][3];f.stride=i<4?1.:i==4?1.259987:.9811;f.speed=i<4?1.02+.06*i:i==4?1.18:.88;}need(c.validate({ground,clear,nullptr}),"all profiles validate lane reference");return c;}
static unsigned inside(const Core&c){unsigned n=0;for(auto&a:c.actors)if(a.view.active)n+=c.protected_point({a.view.x,a.view.y,a.view.z,std::sin(a.view.yaw),std::cos(a.view.yaw)},c.profile(a),true);return n;}
static void quest(){auto c=make();WorldRoadTrafficFrame f;f.dt=1./30;f.player_x=-11988;f.player_z=5172;f.player_feet_y=11.8;f.query={ground,clear,nullptr};for(unsigned i=0;i<300*30;i++){c.update(f);if(i%30==0)need(inside(c)==0,"long wait keeps quest envelopes empty");}need(c.initialized,"all31 spawned");unsigned count=0;for(auto&a:c.actors)count+=a.view.active;need(count==31,"31 traffic actors preserved");
 world_first_journey::Config cfg;cfg.camp={-11988,11.8,5172};cfg.rowan={-11990.15,11.8,5171.35};cfg.bram={-11985.8,11.8,5171.35};cfg.encounter={-11933,12.5028,5312};cfg.supplies={-11930.5,12.5249,5320};cfg.retry={-11933.5,12.4938,5309};cfg.town={-11968,11.8,5582};std::string error;world_first_journey::State state;need(state.configure(cfg,error),"real quest config");world_first_journey::Save save;save.layout_signature=world_first_journey::signature(cfg);save.stage=world_first_journey::Stage::RecoverSupplies;save.camp_spoken=7;save.weapon_unlocked=save.encounter_won=true;need(state.restore(save,error),"actual won checkpoint restore");need(state.encounter_won()&&!state.supplies_recovered(),"win does not imply supplies pickup");
 auto legacy=c;auto old=f;old.player_x=f.player_x=cfg.supplies.x;old.player_z=f.player_z=cfg.supplies.z;old.player_feet_y=f.player_feet_y=cfg.supplies.y;unsigned old_intrusions=0;for(unsigned i=0;i<90*30;i++){f.encounter_cleared=state.supplies_recovered();c.update(f);need(inside(c)==0,"RecoverSupplies keeps all capsule envelopes out");old.encounter_cleared=state.encounter_won();legacy.update(old);old_intrusions=std::max(old_intrusions,inside(legacy));}need(old_intrusions>0,"old host condition reproduces objective traffic intrusion");
 auto snapshot=c.actors;double clock=c.clock;f.paused=true;for(unsigned i=0;i<60;i++)c.update(f);need(c.clock==clock,"paused traffic clock exact");for(unsigned i=0;i<31;i++)need(c.actors[i].station==snapshot[i].station,"pause does not move queues");f.paused=false;
 world_first_journey::Input input;input.player_feet=cfg.supplies;input.dt=1./60;state.tick(input);state.tick(input);input.interact_down=true;auto picked=state.tick(input);need((picked.events&world_first_journey::SuppliesRecovered)&&state.supplies_recovered(),"actual interaction releases protected objective");f.encounter_cleared=state.supplies_recovered();f.player_x=-11988;f.player_z=5172;f.player_feet_y=11.8;const double travelled=c.stats.travelled;bool entered=false;for(unsigned i=0;i<45*30;i++){c.update(f);entered|=inside(c)>0;}need(entered&&c.stats.travelled-travelled>20,"traffic resumes without actor removal after pickup");for(unsigned i=0;i<31;i++)need(c.actors[i].view.active&&c.actors[i].view.id==i,"stable IDs/no respawn or duplicate after release");need(c.stats.failures==0,"no traffic simulation errors");std::printf("Quest protection: old-condition maximum intrusions%u, release travel%.3fm\n",old_intrusions,c.stats.travelled-travelled);
}
static void camera(){auto c=make();c.enabled=c.initialized=true;for(auto&a:c.actors)a.view.active=false;auto&a=c.actors[0];a.view.active=true;a.view.kind=WorldRoadTrafficKind::Walker;a.view.appearance=0;a.view.x=a.view.z=0;a.view.y=12;a.view.yaw=0;auto q=[&](double ax,double ay,double az,double bx,double by,double bz){return c.camera_clear(ax,ay,az,bx,by,bz,.23,.02);};need(!q(-2,13.4,0,2,13.4,0),"human horizontal lens sweep");need(!q(0,13.3,0,0,13.3,0),"stationary lens inside human");need(q(-2,14.3,0,2,14.3,0),"human sweep above fitted head");need(q(-2,11.5,0,2,11.5,0),"human sweep below body");need(!q(0,16,0,0,12.5,0),"descending lens crosses head");need(q(-2,16,0,2,14.4,0),"3D height clipping avoids false XZ blockage");need(!q(-100,13.4,0,100,13.4,0),"long sweep cannot tunnel through human");
 a.view.kind=WorldRoadTrafficKind::Rider;need(!q(-3,14.8,0,3,14.8,0),"horse/rider body includes elevated rider");need(!q(-3,13.1,2.65,3,13.1,2.65),"horse front envelope nose covered");need(!q(-3,13.1,-1.3,3,13.1,-1.3),"horse rear envelope covered");need(q(-3,15.6,0,3,15.6,0),"camera above whole rider clear");need(q(-3,13.1,3.4,3,13.1,3.4),"camera beyond horse front clear");a.view.yaw=pi/2;need(!q(1.9,14.8,-3,1.9,14.8,3),"rotated rider footprint swept");
 a.view.kind=WorldRoadTrafficKind::Pullcart;a.view.yaw=0;need(!q(-3,13,-2.8,3,13,-2.8),"cart rear body/wheels envelope covered");need(q(-3,15.2,-2.8,3,15.2,-2.8),"above cart clear");need(c.blocks(-3,0,3,0,12,1.75,.37),"physical player collision retained");c.enabled=false;need(q(-3,13,-2.8,3,13,-2.8),"disabled traffic does not block camera");c.enabled=true;need(!c.camera_clear(NAN,13,0,1,13,0,.23,.02),"invalid camera inputs fail closed");
 // A moving rider can envelop the previous eye after a previously clear frame.
 // The current boom must still retract to a strict clear prefix, not preserve
 // a historical point now inside moving geometry.
 a.view.kind=WorldRoadTrafficKind::Rider;a.view.x=5;a.view.z=3;WorldFollowCameraSafety safety;WorldCameraPoint pivot{0,13.35,0},desired{0,13.7,3};auto clear_eye=[&](WorldCameraPoint x,WorldCameraPoint y,float r){return c.camera_clear(x.x,x.y,x.z,y.x,y.y,y.z,r,.02);};auto first=safety.update(pivot,desired,.23,1.f/60,true,clear_eye);need(first.view_clear&&world_camera_distance(first.eye,desired)<1e-6,"initial clear following eye");a.view.x=0;auto next=safety.update(pivot,desired,.23,1.f/60,false,clear_eye);need(next.line_blocked,"moving rider occludes boom");need(next.view_clear&&clear_eye(next.eye,next.eye,.23),"moving rider cannot trap retained eye inside body");need(next.eye.z<1.5,"camera retracts in front of horse");
 std::printf("Traffic camera: humans, horses/riders, carts, height, overlap, orbit history checked\n");
}
int main(int argc,char**argv){if(argc>1){char error[256];need(argc==2&&world_road_traffic_config_load(argv[1],test_config,error,sizeof error),"load actual authored traffic settings");}quest();camera();std::printf("PASS %u meaningful traffic/quest/camera checks\n",checks);}
